CREATE TABLE IF NOT EXISTS lease_rent_settings (id INT PRIMARY KEY, template_code VARCHAR(100) NOT NULL DEFAULT '', sender_profile VARCHAR(100) NOT NULL DEFAULT '', gas_key VARCHAR(64) NOT NULL, enabled TINYINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lease_rent_reminders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, contract_id BIGINT UNSIGNED NULL UNIQUE, property VARCHAR(600) NOT NULL, tenant VARCHAR(80) NOT NULL, phone VARCHAR(20) NOT NULL, rent BIGINT NOT NULL, pay_day INT NOT NULL, bank VARCHAR(80) NOT NULL, account_no VARCHAR(80) NOT NULL, holder VARCHAR(80) NOT NULL, late_rate DECIMAL(5,2) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, lead_days INT NOT NULL, send_time TIME NOT NULL, active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lease_rent_send_queue (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reminder_id BIGINT UNSIGNED NOT NULL, rent_month CHAR(7) NOT NULL, due_date DATE NOT NULL, scheduled_at DATETIME NOT NULL, snapshot LONGTEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'pending', UNIQUE KEY uq_month(reminder_id,rent_month), KEY ix_due(status,scheduled_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lease_rent_send_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, queue_id BIGINT UNSIGNED NULL, ref_key VARCHAR(40) NOT NULL, status VARCHAR(20) NOT NULL, result_json LONGTEXT NOT NULL, created_at DATETIME NOT NULL, KEY ix_queue(queue_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
